module.exports=[37642,a=>{"use strict";a.s(["D",0,[{icon:"site",title:"Free Site Visit",text:"We visit, measure and understand your space."},{icon:"quote",title:"Free Quotation",text:"A clear, itemised estimate for your project."},{icon:"design",title:"Free 3D Design",text:"See your home in 3D before work begins."}],"F",0,[{q:"Which cities do you serve?",a:"We take up projects across all of Andhra Pradesh and in Hyderabad — including Vijayawada, Visakhapatnam, Guntur, Tirupati, Nellore, Kadapa, Kurnool, Anantapur and Nandyal, as well as smaller towns. Tell us where your home is and we'll plan a site visit."},{q:"Is the site visit and quotation free?",a:"Yes, site visits and quotations are free within our service locations. Any conditions will be explained when you book."},{q:"What is the free 3D design?",a:"We prepare a 3D design of your space so you can see the proposed interiors before work begins. You decide whether to proceed after reviewing it. Scope and conditions are confirmed during consultation."},{q:"Do you handle single rooms or only complete homes?",a:"Both. We take up individual projects such as a modular kitchen, wardrobes or a TV unit, as well as complete home interiors."},{q:"How long does a project take?",a:"Timelines depend on scope, materials and site readiness. We share a schedule along with your quotation."},{q:"Can I choose the materials and brands?",a:"Yes. Material options, finishes and hardware are discussed and finalised with you during material selection."}],"g",0,[{icon:"design",title:"Personalised Design",text:"Every space is planned around your lifestyle, not a template."},{icon:"measure",title:"Practical Space Planning",text:"Layouts that make the most of every square foot."},{icon:"materials",title:"Material Transparency",text:"Clear specifications for boards, finishes and hardware."},{icon:"execution",title:"Thoughtful Execution",text:"Coordinated work on site with quality checks."},{icon:"detail",title:"Attention to Detail",text:"Edges, alignments, lighting and finishes done with care."},{icon:"consult",title:"Clear Communication",text:"You know what's happening at each stage."}]])}];

